import React from 'react';

const DARK = '#1C1C1E';
const BRAND_PINK = '#FF2D55';

type Props = { title: string; description?: string };

export default function PlaceholderPage({ title, description }: Props) {
  return (
    <div style={{ minHeight: '100%', backgroundColor: DARK }}>
      <div style={{ padding: '1.75rem 2.5rem 1.5rem', backgroundColor: DARK }}>
        <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase', color: BRAND_PINK, marginBottom: 6 }}>Maison</div>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#ffffff', margin: 0, letterSpacing: '-0.03em' }}>
          {title}
        </h1>
        <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.55)', margin: '6px 0 0', maxWidth: 520 }}>
          {description ?? 'This section is coming soon.'}
        </p>
      </div>
    </div>
  );
}
